{
  "root_cause": "The datepicker remains shown when tabbing out of the input, causing the Vanilla Calendar Pro to prevent the Tab key press to keep focus trapped within the calendar. The previous focusout listener hides the datepicker after focus leaves, but the keydown event is prevented before focus moves.",
  "repair_strategy": "Add a keydown listener on the input (capture phase) that hides the datepicker when Tab is pressed while the calendar is shown, allowing the default tab behavior to proceed. Also retain the focusout listener to hide the datepicker when focus leaves via other means.",
  "edits": [
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "  protected declare _onOutside: (event: Event) => void
  protected declare _onTriggerClick: () => void",
      "after": "  protected declare _onOutside: (event: Event) => void
  protected declare _onTriggerClick: () => void
  protected declare _onFocusout: ((event: FocusEvent) => void) | null
  protected declare _onKeydown: ((event: KeyboardEvent) => void) | null"
    },
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "  constructor(element?: string | Element | null, config?: Partial<DatepickerConfig> | null) {
    super(element, config)

    this._calendar = null
    this._isShown = false

    this._initCalendar()
  }",
      "after": "  constructor(element?: string | Element | null, config?: Partial<DatepickerConfig> | null) {
    super(element, config)

    this._calendar = null
    this._isShown = false
    this._onFocusout = null
    this._onKeydown = null

    this._initCalendar()
  }"
    },
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "    this._setupDismiss()

    // Set initial value if input has a value
    if (this._isInput && this._element.value) {
      this._parseInputValue()
    }

    // Populate input/display with preselected dates
    this._updateDisplayWithSelectedDates()
  }",
      "after": "    this._setupDismiss()

    // Hide datepicker when losing focus unless focus is moving to the calendar
    this._onFocusout = (event: FocusEvent) => {
      if (!this._isShown) {
        return
      }
      const calendarMainElement = this._calendar?.context?.mainElement
      if (calendarMainElement && calendarMainElement.contains(event.relatedTarget as Node)) {
        return
      }
      this.hide()
    }

    EventHandler.on(this._element, 'focusout', this._onFocusout)

    // Set initial value if input has a value
    if (this._isInput && this._element.value) {
      this._parseInputValue()
    }

    // Populate input/display with preselected dates
    this._updateDisplayWithSelectedDates()
  }"
    },
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "    EventHandler.on(document, EVENT_FOCUSIN, this._onOutside)
    EventHandler.on(document, EVENT_POINTERDOWN, this._onOutside)
  }",
      "after": "    EventHandler.on(document, EVENT_FOCUSIN, this._onOutside)
    EventHandler.on(document, EVENT_POINTERDOWN, this._onOutside)

    // Hide datepicker on Tab key press from the input to allow focus to move to the next field
    this._onKeydown = (event: KeyboardEvent) => {
      if (this._isShown && event.key === 'Tab' && event.target === this._element) {
        this.hide()
      }
    }
    this._element.addEventListener('keydown', this._onKeydown, { capture: true })
  }"
    },
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "    if (this._onTriggerClick) {
      EventHandler.off(this._positionElement, EVENT_CLICK, this._onTriggerClick)
    }

    if (this._calendar) {
      this._calendar.destroy()
    }

    this._calendar = null
    super.dispose()
  }",
      "after": "    if (this._onTriggerClick) {
      EventHandler.off(this._positionElement, EVENT_CLICK, this._onTriggerClick)
    }

    if (this._onFocusout) {
      EventHandler.off(this._element, 'focusout', this._onFocusout)
      this._onFocusout = null
    }

    if (this._onKeydown) {
      this._element.removeEventListener('keydown', this._onKeydown, { capture: true })
      this._onKeydown = null
    }

    if (this._calendar) {
      this._calendar.destroy()
    }

    this._calendar = null
    super.dispose()
  }"
    }
  ],
  "expected_accessibility_effect": "Tab key will now move focus from the departure date field to the passengers field as expected, while the datepicker is properly dismissed.",
  "functional_risks": [
    "Hiding the datepicker on keydown might interfere with keyboard navigation within the calendar if the user tabs from within the calendar? But the listener only triggers when the target is the input, so calendar internal tabbing is unaffected.",
    "The focusout listener might hide the datepicker when clicking on the calendar? It checks relatedTarget to avoid that."
  ],
  "verification_requirements": [
    "Verify that pressing Tab from the departure date field moves focus to the passengers field.",
    "Verify that the datepicker is hidden when focus leaves the input unless moving to the calendar.",
    "Verify that clicking on a date in the calendar does not hide the calendar prematurely.",
    "Verify that the datepicker still functions correctly for mouse users."
  ]
}
